#include <cstddef>
#include <utility>

class Text
{
public:
    Text(const char* source);
    Text(const Text& other);
    ~Text();
    Text& operator=(Text other);

    friend void swap(Text& a, Text& b) noexcept;

    std::size_t length() const { return m_length; }
    const char* c_str() const { return m_chars; }
    char& operator[](std::size_t i) { return m_chars[i]; }

private:
    char* m_chars{ nullptr };
    std::size_t m_length{ 0 };
};

Text::Text(const char* source)
{
    if (source != nullptr)
    {
        while (source[m_length] != '\0')
        {
            ++m_length;
        }
    }
    m_chars = new char[m_length + 1];
    for (std::size_t i{ 0 }; i < m_length; ++i)
    {
        m_chars[i] = source[i];
    }
    m_chars[m_length] = '\0';
}

Text::Text(const Text& other) : Text{ other.m_chars }
{
}

Text::~Text()
{
    delete[] m_chars;
}

void swap(Text& a, Text& b) noexcept
{
    std::swap(a.m_chars, b.m_chars);
    std::swap(a.m_length, b.m_length);
}

Text& Text::operator=(Text other)
{
    swap(*this, other);
    return *this;
}

unitTests:
TEST("construct") { const Text t{ "hello" }; CHECK_EQ(t.length(), 5u); CHECK_EQ(std::string{ t.c_str() }, "hello"); const Text e{ nullptr }; CHECK_EQ(e.length(), 0u); CHECK_EQ(std::string{ e.c_str() }, ""); }
TEST("copies are independent") { Text a{ "cat" }; Text b{ a }; b[0] = 'b'; CHECK_EQ(std::string{ a.c_str() }, "cat"); CHECK_EQ(std::string{ b.c_str() }, "bat"); }
TEST("assignment") { Text a{ "short" }; Text b{ "a much longer piece of text" }; a = b; CHECK_EQ(std::string{ a.c_str() }, "a much longer piece of text"); CHECK(a.c_str() != b.c_str()); }
TEST("self-assignment") { Text a{ "same" }; Text& alias{ a }; a = alias; CHECK_EQ(std::string{ a.c_str() }, "same"); }
TEST("swap") { Text a{ "one" }, b{ "three" }; swap(a, b); CHECK_EQ(std::string{ a.c_str() }, "three"); CHECK_EQ(b.length(), 3u); }
TEST("no leaks") { CHECK_NO_LEAK(Text a{ "abc" }; Text b{ a }; Text c{ "xyz" }; c = a; a = c; b = b); }

